 71	// Robust depth sampling (median in a local window), ignoring invalid depth
 72	// 深度中值
 73	bool RobustDepthMedianU16(const cv::Mat& depth_mm, int x, int y, int r,
 74	                          uint16_t& out_mm);
 75	
