 77	#include "depth_utils.h"
 78	
 79	#include <algorithm>
 80	#include <vector>
 81	
 82	bool RobustDepthMedianU16(const cv::Mat& depth_mm, int x, int y, int r,
 83	                          uint16_t& out_mm) {
 84	  if (depth_mm.empty() || depth_mm.type() != CV_16UC1) return false;
 85	  std::vector<uint16_t> vals;
 86	  vals.reserve((2 * r + 1) * (2 * r + 1));
 87	  for (int dy = -r; dy <= r; ++dy) {
 88	    int yy = y + dy;
 89	    if (yy < 0 || yy >= depth_mm.rows) continue;
 90	    const uint16_t* row = depth_mm.ptr<uint16_t>(yy);
 91	    for (int dx = -r; dx <= r; ++dx) {
 92	      int xx = x + dx;
 93	      if (xx < 0 || xx >= depth_mm.cols) continue;
 94	      uint16_t z = row[xx];
 95	      // filter invalid (0) / out-of-range
 96	      if (z == 0 || z >= 10000) continue;
 97	      vals.push_back(z);
 98	    }
 99	  }
100	  if (vals.size() < 6) return false;  // too few valid samples
101	  std::nth_element(vals.begin(), vals.begin() + vals.size() / 2, vals.end());
102	  out_mm = vals[vals.size() / 2];
103	  return true;
104	}
