166	void PerfStats::PrintIfNeeded() {
167	  auto now = std::chrono::steady_clock::now();
168	  if (!initialized) {
169	    last_print_time = now;
170	    initialized = true;
171	    return;
172	  }
173	  auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - last_print_time).count();
174	  if (elapsed >= 2) {
175	    PrintStats();
176	    last_print_time = now;
177	  }
178	}
179	
180	void PerfStats::PrintStats() {
181	  auto calc_stats = [](const std::deque<double>& data) -> std::pair<double, double> {
182	    if (data.empty()) return {0, 0};
183	    double sum = 0, max_val = 0;
184	    for (double v : data) { sum += v; if (v > max_val) max_val = v; }
185	    return {sum / data.size(), max_val};
186	  };
187	
188	  auto [inf_avg, inf_max] = calc_stats(inference_ms);
189	  auto [dep_avg, dep_max] = calc_stats(depth_map_ms);
190	  auto [land_avg, land_max] = calc_stats(landing_detect_ms);
191	
192	  std::cout << "[Perf] Inference: " << std::fixed << std::setprecision(1)
193	            << inf_avg << "/" << inf_max << "ms"
194	            << " | Depth: " << dep_avg << "/" << dep_max << "ms"
195	            << " | Landing: " << land_avg << "/" << land_max << "ms" << std::endl;
196	}
