 32	    if (use_cuda_) {
 33	        try {
 34	            OrtCUDAProviderOptions cuda_options;
 35	            cuda_options.device_id = 0;  // GPU 设备 ID
 36	            cuda_options.arena_extend_strategy = 0;
 37	            cuda_options.cudnn_conv_algo_search = OrtCudnnConvAlgoSearchExhaustive;
 38	            cuda_options.do_copy_in_default_stream = 1;
 39	            session_options_.AppendExecutionProvider_CUDA(cuda_options);
 40	            std::cout << "✓ CUDA execution provider configured (GPU 0)" << std::endl;
 41	        } catch (const Ort::Exception& e) {
 42	            std::cerr << "Warning: Failed to configure CUDA: " << e.what() << std::endl;
 43	            std::cerr << "Falling back to CPU execution" << std::endl;
 44	            use_cuda_ = false;
 45	        }
 46	    }
 47	}
