119	void YOLOPoseDetector::Preprocess(
120	    const cv::Mat& image,
121	    std::vector<float>& input_data) {
122	
123	    // Letterbox resize (maintain aspect ratio)
124	    int img_h = image.rows;
125	    int img_w = image.cols;
126	
127	    scale_factor_ = std::min(
128	        static_cast<float>(input_size_) / img_w,
129	        static_cast<float>(input_size_) / img_h);
130	
131	    int new_w = static_cast<int>(img_w * scale_factor_);
132	    int new_h = static_cast<int>(img_h * scale_factor_);
133	
134	    pad_w_ = (input_size_ - new_w) / 2;
135	    pad_h_ = (input_size_ - new_h) / 2;
136	
137	    // Resize
138	    cv::Mat resized;
139	    cv::resize(image, resized, cv::Size(new_w, new_h));
140	
141	    // Add padding
142	    cv::Mat padded;
143	    cv::copyMakeBorder(
144	        resized, padded,
145	        pad_h_, input_size_ - new_h - pad_h_,
146	        pad_w_, input_size_ - new_w - pad_w_,
147	        cv::BORDER_CONSTANT, cv::Scalar(114, 114, 114));
148	
149	    // BGR to RGB
150	    cv::Mat rgb;
151	    cv::cvtColor(padded, rgb, cv::COLOR_BGR2RGB);
152	
153	    // Normalize to [0, 1] and convert to float
154	    rgb.convertTo(rgb, CV_32F, 1.0 / 255.0);
155	
156	    // HWC to CHW format
157	    input_data.resize(3 * input_size_ * input_size_);
158	    std::vector<cv::Mat> channels(3);
159	    cv::split(rgb, channels);
160	
161	    int channel_size = input_size_ * input_size_;
162	    for (int c = 0; c < 3; c++) {
163	        std::memcpy(
164	            input_data.data() + c * channel_size,
165	            channels[c].data,
166	            channel_size * sizeof(float));
167	    }
168	}
