170	std::vector<PoseResult> YOLOPoseDetector::Detect(const cv::Mat& image) {
171	    if (!initialized_) {
172	        std::cerr << "Detector not initialized! Call Init() first." << std::endl;
173	        return {};
174	    }
175	
176	    if (image.empty()) {
177	        std::cerr << "Empty image!" << std::endl;
178	        return {};
179	    }
180	
181	    // Preprocess
182	    std::vector<float> input_data;
183	    Preprocess(image, input_data);
184	
185	    // Create input tensor
186	    std::vector<int64_t> input_shape = {1, 3, input_size_, input_size_};
187	    Ort::MemoryInfo memory_info = Ort::MemoryInfo::CreateCpu(
188	        OrtArenaAllocator, OrtMemTypeDefault);
189	
190	    Ort::Value input_tensor = Ort::Value::CreateTensor<float>(
191	        memory_info,
192	        input_data.data(),
193	        input_data.size(),
194	        input_shape.data(),
195	        input_shape.size());
196	
197	    // Run inference
198	    auto output_tensors = session_->Run(
199	        Ort::RunOptions{nullptr},
200	        input_names_ptrs_.data(),
201	        &input_tensor,
202	        1,
203	        output_names_ptrs_.data(),
204	        1);
205	
206	    // Get output data
207	    float* output_data = output_tensors[0].GetTensorMutableData<float>();
208	
209	    // Postprocess
210	    std::vector<PoseResult> results = Postprocess(output_data, image.size());
211	
212	    return results;
213	}
