215	std::vector<PoseResult> YOLOPoseDetector::Postprocess(
216	    float* output,
217	    const cv::Size& original_size) {
218	
219	    // YOLOv8-pose output format: [1, 56, 8400]
220	    // 56 = 4 (bbox: cx, cy, w, h) + 1 (confidence) + 17*3 (keypoints: x, y, visibility)
221	    // Note: YOLOv8-pose uses visibility (0-1) not confidence for keypoints
222	    // 8400 = detection proposals
223	
224	    int num_proposals = output_shape_[2];  // 8400
225	    int num_elements = output_shape_[1];   // 56
226	
227	    std::vector<PoseResult> proposals;
228	
229	    // Transpose from [1, 56, 8400] to [8400, 56] for easier access
230	    std::vector<float> transposed(num_proposals * num_elements);
231	    for (int i = 0; i < num_proposals; i++) {
232	        for (int j = 0; j < num_elements; j++) {
233	            transposed[i * num_elements + j] = output[j * num_proposals + i];
234	        }
235	    }
236	
237	    // Parse each proposal
238	    for (int i = 0; i < num_proposals; i++) {
239	        float* ptr = transposed.data() + i * num_elements;
240	
241	        // Extract bbox (center_x, center_y, width, height)
242	        float cx = ptr[0];
243	        float cy = ptr[1];
244	        float w = ptr[2];
245	        float h = ptr[3];
246	
247	        // Extract confidence (person detection confidence)
248	        float conf = ptr[4];
249	
250	        if (conf < conf_threshold_) {
251	            continue;
252	        }
253	
254	        // Create result
255	        PoseResult result;
256	        result.box_confidence = conf;
257	
258	        // Convert bbox from center format to corner format
259	        float x1 = cx - w / 2;
260	        float y1 = cy - h / 2;
261	        result.bbox = cv::Rect(
262	            static_cast<int>(x1),
263	            static_cast<int>(y1),
264	            static_cast<int>(w),
265	            static_cast<int>(h));
266	
267	        // Extract 17 keypoints (x, y, visibility)
268	        // Keypoints start at index 5 (not 6!)
269	        // Format: x, y, visibility (where visibility is 0-1, similar to confidence)
270	        for (int k = 0; k < 17; k++) {
271	            float kp_x = ptr[5 + k * 3 + 0];
272	            float kp_y = ptr[5 + k * 3 + 1];
273	            float kp_visibility = ptr[5 + k * 3 + 2];
274	
275	            result.keypoints[k] = KeyPoint(kp_x, kp_y, kp_visibility);
276	        }
277	
278	        proposals.push_back(result);
279	    }
280	
281	    // Apply NMS
282	    std::vector<PoseResult> nms_results = NonMaximumSuppression(proposals);
283	
284	    // Rescale coordinates to original image size
285	    for (auto& result : nms_results) {
286	        RescaleCoordinates(result, original_size);
287	    }
288	
289	    return nms_results;
290	}
