292	std::vector<PoseResult> YOLOPoseDetector::NonMaximumSuppression(
293	    std::vector<PoseResult>& proposals) {
294	
295	    if (proposals.empty()) {
296	        return {};
297	    }
298	
299	    // Sort by confidence (descending)
300	    std::sort(proposals.begin(), proposals.end(),
301	        [](const PoseResult& a, const PoseResult& b) {
302	            return a.box_confidence > b.box_confidence;
303	        });
304	
305	    std::vector<bool> suppressed(proposals.size(), false);
306	    std::vector<PoseResult> results;
307	
308	    for (size_t i = 0; i < proposals.size(); i++) {
309	        if (suppressed[i]) {
310	            continue;
311	        }
312	
313	        results.push_back(proposals[i]);
314	
315	        // Suppress overlapping boxes
316	        for (size_t j = i + 1; j < proposals.size(); j++) {
317	            if (suppressed[j]) {
318	                continue;
319	            }
320	
321	            float iou = CalculateIoU(proposals[i].bbox, proposals[j].bbox);
322	            if (iou > iou_threshold_) {
323	                suppressed[j] = true;
324	            }
325	        }
326	    }
327	
328	    return results;
329	}
330	
331	float YOLOPoseDetector::CalculateIoU(
332	    const cv::Rect& box1,
333	    const cv::Rect& box2) {
334	
335	    int x1 = std::max(box1.x, box2.x);
336	    int y1 = std::max(box1.y, box2.y);
337	    int x2 = std::min(box1.x + box1.width, box2.x + box2.width);
338	    int y2 = std::min(box1.y + box1.height, box2.y + box2.height);
339	
340	    int intersection_area = std::max(0, x2 - x1) * std::max(0, y2 - y1);
341	    int box1_area = box1.width * box1.height;
342	    int box2_area = box2.width * box2.height;
343	    int union_area = box1_area + box2_area - intersection_area;
344	
345	    return static_cast<float>(intersection_area) / union_area;
346	}
