348	void YOLOPoseDetector::RescaleCoordinates(
349	    PoseResult& result,
350	    const cv::Size& original_size) {
351	
352	    // Remove padding and rescale
353	    auto rescale = [&](float& x, float& y) {
354	        x = (x - pad_w_) / scale_factor_;
355	        y = (y - pad_h_) / scale_factor_;
356	
357	        // Clamp to image bounds
358	        x = std::max(0.0f, std::min(x, static_cast<float>(original_size.width - 1)));
359	        y = std::max(0.0f, std::min(y, static_cast<float>(original_size.height - 1)));
360	    };
361	
362	    // Rescale bbox
363	    float x1 = result.bbox.x;
364	    float y1 = result.bbox.y;
365	    float x2 = result.bbox.x + result.bbox.width;
366	    float y2 = result.bbox.y + result.bbox.height;
367	
368	    rescale(x1, y1);
369	    rescale(x2, y2);
370	
371	    result.bbox = cv::Rect(
372	        static_cast<int>(x1),
373	        static_cast<int>(y1),
374	        static_cast<int>(x2 - x1),
375	        static_cast<int>(y2 - y1));
376	
377	    // Rescale keypoints
378	    for (auto& kp : result.keypoints) {
379	        rescale(kp.x, kp.y);
380	    }
381	}

