 44	void MapPoseTo3D(
 45	    std::vector<PoseResult>& poses,
 46	    const cv::Mat& depth,
 47	    const cv::Mat& camera_matrix) {
 48	
 49	    if (depth.empty() || camera_matrix.empty()) {
 50	        return;
 51	    }
 52	
 53	    // Extract camera intrinsics
 54	    double fx = camera_matrix.at<double>(0, 0);
 55	    double fy = camera_matrix.at<double>(1, 1);
 56	    double cx = camera_matrix.at<double>(0, 2);
 57	    double cy = camera_matrix.at<double>(1, 2);
 58	
 59	    for (auto& pose : poses) {
 60	        for (auto& kp : pose.keypoints) {
 61	            // Skip if confidence too low
 62	            if (kp.confidence < 0.3f) {
 63	                continue;
 64	            }
 65	
 66	            int x = cvRound(kp.x);
 67	            int y = cvRound(kp.y);
 68	
 69	            // Check bounds
 70	            if (x < 0 || x >= depth.cols || y < 0 || y >= depth.rows) {
 71	                continue;
 72	            }
 73	
 74	            // Get depth value (in millimeters)
 75	            ushort Z_mm = depth.at<ushort>(y, x);
 76	
 77	            // Check if depth is valid
 78	            if (Z_mm >= 10000 || Z_mm == 0) {
 79	                continue;
 80	            }
 81	
 82	            // Convert to meters for calculations
 83	            double Z = Z_mm / 1000.0;
 84	
 85	            // Project to 3D (in left camera coordinate system)
 86	            // X = (u - cx) * Z / fx
 87	            // Y = (v - cy) * Z / fy
 88	            // Z = Z
 89	            double X = (x - cx) * Z / fx;
 90	            double Y = (y - cy) * Z / fy;
 91	
 92	            // Store 3D position (in millimeters)
 93	            kp.pos3d.x = static_cast<float>(X * 1000.0);
 94	            kp.pos3d.y = static_cast<float>(Y * 1000.0);
 95	            kp.pos3d.z = static_cast<float>(Z * 1000.0);
 96	        }
 97	    }
 98	}
