100	void DrawPoses(
101	    cv::Mat& image,
102	    const std::vector<PoseResult>& poses,
103	    bool show_bbox,
104	    bool show_keypoints,
105	    bool show_skeleton,
106	    float keypoint_conf_threshold) {
107	
108	    auto skeleton = GetCocoSkeleton();
109	
110	    for (const auto& pose : poses) {
111	        // Draw bounding box
112	        if (show_bbox) {
113	            cv::rectangle(image, pose.bbox, cv::Scalar(0, 255, 0), 2);
114	
115	            // Draw confidence
116	            std::ostringstream ss;
117	            ss << std::fixed << std::setprecision(2) << pose.box_confidence;
118	            cv::putText(
119	                image, ss.str(),
120	                cv::Point(pose.bbox.x, pose.bbox.y - 5),
121	                cv::FONT_HERSHEY_SIMPLEX, 0.5,
122	                cv::Scalar(0, 255, 0), 2);
123	        }
124	
125	        // Draw skeleton connections
126	        if (show_skeleton) {
127	            for (const auto& conn : skeleton) {
128	                const auto& kp1 = pose.keypoints[conn.start_idx];
129	                const auto& kp2 = pose.keypoints[conn.end_idx];
130	
131	                if (kp1.confidence > keypoint_conf_threshold &&
132	                    kp2.confidence > keypoint_conf_threshold) {
133	                    cv::line(
134	                        image,
135	                        cv::Point(cvRound(kp1.x), cvRound(kp1.y)),
136	                        cv::Point(cvRound(kp2.x), cvRound(kp2.y)),
137	                        conn.color, 2);
138	                }
139	            }
140	        }
141	
142	        // Draw keypoints
143	        if (show_keypoints) {
144	            for (size_t i = 0; i < pose.keypoints.size(); i++) {
145	                const auto& kp = pose.keypoints[i];
146	
147	                if (kp.confidence > keypoint_conf_threshold) {
148	                    // Color based on confidence
149	                    cv::Scalar color;
150	                    if (kp.confidence > 0.8f) {
151	                        color = cv::Scalar(0, 0, 255);  // Red - high confidence
152	                    } else if (kp.confidence > 0.6f) {
153	                        color = cv::Scalar(0, 165, 255);  // Orange - medium
154	                    } else {
155	                        color = cv::Scalar(0, 255, 255);  // Yellow - low
156	                    }
157	
158	                    cv::circle(
159	                        image,
160	                        cv::Point(cvRound(kp.x), cvRound(kp.y)),
161	                        5, color, -1);
162	
163	                    // Optionally draw keypoint index
164	                    // cv::putText(image, std::to_string(i),
165	                    //     cv::Point(kp.x + 5, kp.y - 5),
166	                    //     cv::FONT_HERSHEY_SIMPLEX, 0.3, color, 1);
167	                }
168	            }
169	        }
170	    }
171	}
