173	void DrawPoseInfo(
174	    cv::Mat& image,
175	    const std::vector<PoseResult>& poses,
176	    bool show_depth) {
177	
178	    int y_offset = 30;
179	    int line_height = 25;
180	
181	    for (size_t i = 0; i < poses.size(); i++) {
182	        const auto& pose = poses[i];
183	
184	        // Person label
185	        std::ostringstream ss;
186	        ss << "Person " << (i + 1);
187	        cv::putText(
188	            image, ss.str(),
189	            cv::Point(10, y_offset),
190	            cv::FONT_HERSHEY_SIMPLEX, 0.6,
191	            cv::Scalar(255, 255, 255), 2);
192	        y_offset += line_height;
193	
194	        // Confidence
195	        ss.str("");
196	        ss << "  Conf: " << std::fixed << std::setprecision(2)
197	           << pose.box_confidence;
198	        cv::putText(
199	            image, ss.str(),
200	            cv::Point(10, y_offset),
201	            cv::FONT_HERSHEY_SIMPLEX, 0.5,
202	            cv::Scalar(200, 200, 200), 1);
203	        y_offset += line_height;
204	
205	        // 3D depth information
206	        if (show_depth) {
207	            // Calculate average depth from visible keypoints
208	            float sum_depth = 0;
209	            int count = 0;
210	            for (const auto& kp : pose.keypoints) {
211	                if (kp.confidence > 0.5f && kp.pos3d.z > 0) {
212	                    sum_depth += kp.pos3d.z;
213	                    count++;
214	                }
215	            }
216	
217	            if (count > 0) {
218	                float avg_depth = sum_depth / count;
219	                ss.str("");
220	                ss << "  Depth: " << std::fixed << std::setprecision(2)
221	                   << (avg_depth / 1000.0) << " m";
222	                cv::putText(
223	                    image, ss.str(),
224	                    cv::Point(10, y_offset),
225	                    cv::FONT_HERSHEY_SIMPLEX, 0.5,
226	                    cv::Scalar(200, 200, 200), 1);
227	                y_offset += line_height;
228	            }
229	
230	            // Estimate height
231	            float height = EstimateBodyHeight(pose);
232	            if (height > 0) {
233	                ss.str("");
234	                ss << "  Height: " << std::fixed << std::setprecision(0)
235	                   << height << " mm";
236	                cv::putText(
237	                    image, ss.str(),
238	                    cv::Point(10, y_offset),
239	                    cv::FONT_HERSHEY_SIMPLEX, 0.5,
240	                    cv::Scalar(200, 200, 200), 1);
241	                y_offset += line_height;
242	            }
243	        }
244	
245	        y_offset += 10;  // Space between people
246	    }
247	}
