263	float Calculate3DDistance(const KeyPoint& kp1, const KeyPoint& kp2) {
264	    // Check if both keypoints have valid 3D coordinates
265	    if (kp1.pos3d.z <= 0 || kp2.pos3d.z <= 0) {
266	        return -1.0f;
267	    }
268	
269	    // Euclidean distance in 3D
270	    float dx = kp1.pos3d.x - kp2.pos3d.x;
271	    float dy = kp1.pos3d.y - kp2.pos3d.y;
272	    float dz = kp1.pos3d.z - kp2.pos3d.z;
273	
274	    return std::sqrt(dx * dx + dy * dy + dz * dz);
275	}
