277	float EstimateBodyHeight(const PoseResult& pose) {
278	    // Try multiple methods to estimate height
279	
280	    // Method 1: Top of head to ankle
281	    const auto& nose = pose.keypoints[NOSE];
282	    const auto& left_ankle = pose.keypoints[LEFT_ANKLE];
283	    const auto& right_ankle = pose.keypoints[RIGHT_ANKLE];
284	
285	    float height = -1.0f;
286	
287	    // Use the ankle with higher confidence
288	    const KeyPoint* ankle = nullptr;
289	    if (left_ankle.confidence > right_ankle.confidence &&
290	        left_ankle.confidence > 0.5f) {
291	        ankle = &left_ankle;
292	    } else if (right_ankle.confidence > 0.5f) {
293	        ankle = &right_ankle;
294	    }
295	
296	    if (ankle != nullptr && nose.confidence > 0.5f) {
297	        height = Calculate3DDistance(nose, *ankle);
298	    }
299	
300	    // Method 2: If ankles not visible, try knee to head
301	    if (height < 0) {
302	        const auto& left_knee = pose.keypoints[LEFT_KNEE];
303	        const auto& right_knee = pose.keypoints[RIGHT_KNEE];
304	
305	        const KeyPoint* knee = nullptr;
306	        if (left_knee.confidence > right_knee.confidence &&
307	            left_knee.confidence > 0.5f) {
308	            knee = &left_knee;
309	        } else if (right_knee.confidence > 0.5f) {
310	            knee = &right_knee;
311	        }
312	
313	        if (knee != nullptr && nose.confidence > 0.5f) {
314	            float partial_height = Calculate3DDistance(nose, *knee);
315	            if (partial_height > 0) {
316	                // Estimate full height (knee to head is roughly 70% of full height)
317	                height = partial_height / 0.7f;
318	            }
319	        }
320	    }
321	
322	    return height;
323	}

