352	static bool BuildBodyFrameFromPose(const PoseResult &pose,
353	                                   const Pose3DInfo &info,
354	                                   const cv::Mat &R_bed_cam,
355	                                   BodyFrame &out) {
356	  if (R_bed_cam.empty()) {
357	    return false;
358	  }
359	
360	  auto kp_ok = [&](int idx, cv::Point3d &pt) -> bool {
361	    if (idx < 0 || idx >= static_cast<int>(info.kp_bed.size())) {
362	      return false;
363	    }
364	    if (!info.kp_valid[idx]) {
365	      return false;
366	    }
367	    if (pose.keypoints[idx].confidence < 0.3f) {
368	      return false;
369	    }
370	    pt = info.kp_bed[idx];
371	    return true;
372	  };
373	
374	  cv::Point3d lh, rh, ls, rs;
375	  bool lh_ok = kp_ok(LEFT_HIP, lh);
376	  bool rh_ok = kp_ok(RIGHT_HIP, rh);
377	  bool ls_ok = kp_ok(LEFT_SHOULDER, ls);
378	  bool rs_ok = kp_ok(RIGHT_SHOULDER, rs);
379	
380	  if ((!lh_ok && !rh_ok) || (!ls_ok && !rs_ok)) {
381	    return false;
382	  }
383	
384	  cv::Point3d pelvis = lh_ok && rh_ok
385	                           ? cv::Point3d(0.5 * (lh.x + rh.x), 0.5 * (lh.y + rh.y), 0.5 * (lh.z + rh.z))
386	                           : (lh_ok ? lh : rh);
387	
388	  cv::Point3d shoulders = ls_ok && rs_ok
389	                              ? cv::Point3d(0.5 * (ls.x + rs.x), 0.5 * (ls.y + rs.y), 0.5 * (ls.z + rs.z))
390	                              : (ls_ok ? ls : rs);
391	
392	  // Define body axes in bed coordinates:
393	  // y_body: hip_mid -> shoulder_mid
394	  // x_body: right_hip -> left_hip (left minus right)
395	  // z_body: x_body × y_body
396	  cv::Vec3d y_raw(shoulders.x - pelvis.x, shoulders.y - pelvis.y, shoulders.z - pelvis.z);
397	  cv::Vec3d x_raw(0.0, 0.0, 0.0);
398	  if (lh_ok && rh_ok) {
399	    x_raw = cv::Vec3d(lh.x - rh.x, lh.y - rh.y, lh.z - rh.z);
400	  } else if (ls_ok && rs_ok) {
401	    x_raw = cv::Vec3d(ls.x - rs.x, ls.y - rs.y, ls.z - rs.z);
402	  } else {
403	    return false;
404	  }
405	
406	  cv::Vec3d x_axis;
407	  if (!NormalizeVec(x_raw, x_axis)) {
408	    return false;
409	  }
410	
411	  // Gram-Schmidt: make y orthogonal to x, then normalize.
412	  cv::Vec3d y_orth = y_raw - x_axis * (y_raw.dot(x_axis));
413	  cv::Vec3d y_axis;
414	  if (!NormalizeVec(y_orth, y_axis)) {
415	    return false;
416	  }
417	
418	  cv::Vec3d z_axis = x_axis.cross(y_axis);
419	  if (!NormalizeVec(z_axis, z_axis)) {
420	    return false;
421	  }
422	
423	  out.origin_bed = pelvis;
424	  out.R_body_bed = cv::Mat::eye(3, 3, CV_64F);
425	  out.R_body_bed.at<double>(0, 0) = x_axis[0];
426	  out.R_body_bed.at<double>(1, 0) = x_axis[1];
427	  out.R_body_bed.at<double>(2, 0) = x_axis[2];
428	
429	  out.R_body_bed.at<double>(0, 1) = y_axis[0];
430	  out.R_body_bed.at<double>(1, 1) = y_axis[1];
431	  out.R_body_bed.at<double>(2, 1) = y_axis[2];
432	
433	  out.R_body_bed.at<double>(0, 2) = z_axis[0];
434	  out.R_body_bed.at<double>(1, 2) = z_axis[1];
435	  out.R_body_bed.at<double>(2, 2) = z_axis[2];
436	
437	  out.R_body_cam = R_bed_cam * out.R_body_bed;
438	  out.R_rel = R_bed_cam.t() * out.R_body_cam;
439	  out.quat = RotationMatrixToQuaternion(out.R_rel);
440	  out.euler_rad = RotationMatrixToEulerXYZ(out.R_rel);
441	  out.valid = true;
442	  return true;
443	}
