 68	struct RotationTracker {
 69	  bool initialized = false;
 70	  cv::Vec3d last_angles{0.0, 0.0, 0.0};
 71	  cv::Vec3d cumulative{0.0, 0.0, 0.0};
 72	
 73	  void Reset() {
 74	    initialized = false;
 75	    last_angles = cv::Vec3d(0.0, 0.0, 0.0);
 76	    cumulative = cv::Vec3d(0.0, 0.0, 0.0);
 77	  }
 78	
 79	  void Update(const cv::Vec3d &angles_rad) {
 80	    if (!initialized) {
 81	      last_angles = angles_rad;
 82	      initialized = true;
 83	      return;
 84	    }
 85	    for (int i = 0; i < 3; ++i) {
 86	      double delta = angles_rad[i] - last_angles[i];
 87	      while (delta > M_PI) delta -= 2.0 * M_PI;
 88	      while (delta < -M_PI) delta += 2.0 * M_PI;
 89	      cumulative[i] += delta;
 90	      last_angles[i] = angles_rad[i];
 91	    }
 92	  }
 93	};
