284	  bool TryFinalizePlaneFromROI(const cv::Mat &depth) {
285	    if (!pending_roi_finalize_) {
286	      return false;
287	    }
288	    pending_roi_finalize_ = false;
289	
290	    if (roi_points_.size() != 4) {
291	      return false;
292	    }
293	    if (depth.empty() || depth.type() != CV_16UC1) {
294	      std::cout << "[WARN] Depth map unavailable for plane fit." << std::endl;
295	      return false;
296	    }
297	
298	    std::vector<cv::Point> ordered_roi;
299	    cv::convexHull(roi_points_, ordered_roi, true);
300	    if (ordered_roi.size() != 4) {
301	      std::cout << "[WARN] ROI points are degenerate; please reselect." << std::endl;
302	      return false;
303	    }
304	    roi_points_ = ordered_roi;
305	
306	    cv::Mat mask(depth.rows, depth.cols, CV_8UC1, cv::Scalar(0));
307	    std::vector<std::vector<cv::Point>> poly(1, roi_points_);
308	    cv::fillPoly(mask, poly, cv::Scalar(255));
309	
310	    std::vector<cv::Point3d> samples;
311	    samples.reserve(2000);
312	
313	    const int step = roi_sample_step_;
314	    for (int y = 0; y < depth.rows; y += step) {
315	      const uint16_t *row = depth.ptr<uint16_t>(y);
316	      const uint8_t *mrow = mask.ptr<uint8_t>(y);
317	      for (int x = 0; x < depth.cols; x += step) {
318	        if (mrow[x] == 0) continue;
319	        uint16_t z_mm = row[x];
320	        if (z_mm == 0 || z_mm >= 10000) continue;
321	        cv::Mat pt_img = (cv::Mat_<double>(3, 1) << static_cast<double>(x),
322	                          static_cast<double>(y), 1.0);
323	        cv::Mat pt_cam = cv_in_left_inv * static_cast<double>(z_mm) * pt_img;
324	        samples.emplace_back(pt_cam.at<double>(0, 0),
325	                             pt_cam.at<double>(1, 0),
326	                             pt_cam.at<double>(2, 0));
327	      }
328	    }
329	
330	    if (samples.size() < 50) {
331	      std::cout << "[WARN] Not enough depth samples in ROI (" << samples.size() << ")." << std::endl;
332	      return false;
333	    }
334	
335	    std::vector<int> inlier_idx;
336	    cv::Vec4d plane_ransac;
337	    bool ok = FitPlaneRansac(samples, ransac_max_iters_, ransac_inlier_thresh_mm_, inlier_idx, plane_ransac);
338	    if (!ok) {
339	      std::cout << "[WARN] RANSAC plane fit failed." << std::endl;
340	      return false;
341	    }
342	
343	    std::vector<cv::Point3d> inliers;
344	    inliers.reserve(inlier_idx.size());
345	    for (int idx : inlier_idx) {
346	      inliers.push_back(samples[idx]);
347	    }
348	
349	    cv::Vec4d plane_refined;
350	    if (!FitPlaneLeastSquares(inliers, plane_refined)) {
351	      std::cout << "[WARN] Refined plane fit failed." << std::endl;
352	      return false;
353	    }
354	
355	    plane_coeffs_ = plane_refined;
356	    plane_inlier_count_ = static_cast<int>(inliers.size());
357	    plane_inlier_ratio_ = static_cast<double>(inliers.size()) / static_cast<double>(samples.size());
358	    plane_fit_ready_ = true;
359	
360	    if (!BuildFrameFromPlane(plane_refined, inliers)) {
361	      std::cout << "[WARN] Failed to build trampoline frame from plane." << std::endl;
362	      return false;
363	    }
364	
365	    std::cout << "\n[Trampoline Plane Established]" << std::endl;
366	    std::cout << "Plane: n=[" << plane_refined[0] << ", " << plane_refined[1] << ", " << plane_refined[2]
367	              << "], d=" << plane_refined[3] << std::endl;
368	    std::cout << "Inliers: " << plane_inlier_count_ << " / " << samples.size()
369	              << " (" << std::fixed << std::setprecision(1) << (plane_inlier_ratio_ * 100.0) << "%)" << std::endl;
370	
371	    return true;
372	  }
