375	   * Transform a point from camera coordinate system to new coordinate system.
376	   * Returns cv::Point3d with transformed coordinates.
377	   */
378	  cv::Point3d TransformToNewFrame(const cv::Point3d &point_cam) const {
379	    if (!coord_system_ready_) {
380	      return cv::Point3d(0, 0, 0);
381	    }
382	
383	    // Translate: relative to origin
384	    cv::Point3d relative(point_cam.x - origin_.x,
385	                        point_cam.y - origin_.y,
386	                        point_cam.z - origin_.z);
387	
388	    // Rotate: new_coords = R^T * relative
389	    cv::Point3d new_coords;
390	    new_coords.x = rotation_matrix_.at<double>(0, 0) * relative.x +
391	                   rotation_matrix_.at<double>(1, 0) * relative.y +
392	                   rotation_matrix_.at<double>(2, 0) * relative.z;
393	
394	    new_coords.y = rotation_matrix_.at<double>(0, 1) * relative.x +
395	                   rotation_matrix_.at<double>(1, 1) * relative.y +
396	                   rotation_matrix_.at<double>(2, 1) * relative.z;
397	
398	    new_coords.z = rotation_matrix_.at<double>(0, 2) * relative.x +
399	                   rotation_matrix_.at<double>(1, 2) * relative.y +
400	                   rotation_matrix_.at<double>(2, 2) * relative.z;
401	
402	    return new_coords;
403	  }
