548	    // Simple adaptive EMA filter for 3D points
549	  struct EMA3 {
550	        bool init = false;
551	        cv::Point3d v{0, 0, 0};
552	        double fc = 6.0;  // cutoff frequency (Hz)
553	        cv::Point3d Step(const cv::Point3d& x, double dt_sec) {
554	            if (!init) {
555	                v = x;
556	                init = true;
557	                return v;
558	              }
559	            if (dt_sec <= 0) dt_sec = 1.0 / 50.0;
560	            double a = 1.0 - std::exp(-2.0 * M_PI * fc * dt_sec);
561	            v = v + a * (x - v);
562	            return v;
563	          }
564	        void Reset() { init = false; v = cv::Point3d(0, 0, 0); }
565	      };
