580	    // Pick a stable target (avoid poses ordering jitter): choose hip closest to last tracked cam pos
581	    int PickTrackedHipIndex(const std::vector<HipInfo>& hips) {
582	        if (hips.empty()) return -1;
583	        int best = 0;
584	        if (!has_last_track_) {
585	            return 0;
586	          }
587	        double best_d2 = std::numeric_limits<double>::infinity();
588	        for (int i = 0; i < (int)hips.size(); ++i) {
589	            const auto& p = hips[i].camera_pos;
590	            double dx = p.x - last_track_cam_pos_.x;
591	            double dy = p.y - last_track_cam_pos_.y;
592	            double dz = p.z - last_track_cam_pos_.z;
593	            double d2 = dx * dx + dy * dy + dz * dz;
594	            if (d2 < best_d2) {
595	                best_d2 = d2;
596	                best = i;
597	              }
598	          }
599	        return best;
600	      }
