677	  /**
678	   * Check if the current frame represents a landing point (local minimum of new frame Z).
679	   * Uses delayed confirmation and Z-weighted averaging for improved accuracy.
680	   *
681	   * Algorithm:
682	   * 1. Store frame data in a circular buffer
683	   * 2. Detect potential minimum when Z transitions from descending to ascending
684	   * 3. Wait for CONFIRM_FRAMES to confirm the minimum
685	   * 4. Calculate weighted average of X, Y coordinates (weight based on Z proximity to minimum)
686	   */
687	  void CheckLandingPoint(const HipInfo &hip) {
688	    double current_z = hip.new_frame_pos.z;
689	    auto now = std::chrono::steady_clock::now();
690	
691	    // Add current frame to buffer
692	    FrameData fd;
693	    fd.x = hip.new_frame_pos.x;
694	    fd.y = hip.new_frame_pos.y;
695	    fd.z = hip.new_frame_pos.z;
696	    fd.timestamp = now;
697	    frame_buffer_.push_back(fd);
698	
699	    // Keep buffer size limited
700	    while (frame_buffer_.size() > BUFFER_SIZE) {
701	      frame_buffer_.pop_front();
702	      // Adjust pending index if we removed elements
703	      if (has_pending_minimum_ && pending_min_index_ > 0) {
704	        pending_min_index_--;
705	      } else if (has_pending_minimum_ && pending_min_index_ <= 0) {
706	        // Lost the pending minimum due to buffer overflow
707	        has_pending_minimum_ = false;
708	        pending_min_index_ = -1;
709	        frames_since_minimum_ = 0;
710	      }
711	    }
712	
713	    // Need at least 2 frames to detect trend
714	    if (frame_buffer_.size() < 2) {
715	      last_new_z_ = current_z;
716	      return;
717	    }
718	
719	    // Use member variable for noise threshold (adjustable at runtime)
720	    double noise_threshold = noise_threshold_;
721	
722	    // Check if we have a pending minimum to confirm
723	    if (has_pending_minimum_) {
724	      frames_since_minimum_++;
725	
726	      // Check if current Z is still higher than the pending minimum (confirming upward trend)
727	      double min_z = frame_buffer_[pending_min_index_].z;
728	      bool still_ascending = (current_z > min_z + noise_threshold * 0.5);
729	
730	      if (still_ascending && frames_since_minimum_ >= static_cast<int>(CONFIRM_FRAMES)) {
731	        // Confirmed! Calculate weighted average and record landing point
732	        ConfirmLandingPoint();
733	        has_pending_minimum_ = false;
734	        pending_min_index_ = -1;
735	        frames_since_minimum_ = 0;
736	        was_descending_ = false;
737	      } else if (!still_ascending && current_z < min_z) {
738	        // Found a new lower point, update pending minimum
739	        pending_min_index_ = static_cast<int>(frame_buffer_.size()) - 1;
740	        frames_since_minimum_ = 0;
741	      } else if (frames_since_minimum_ > static_cast<int>(BUFFER_SIZE)) {
742	        // Timeout, cancel pending minimum
743	        has_pending_minimum_ = false;
744	        pending_min_index_ = -1;
745	        frames_since_minimum_ = 0;
746	      }
747	    } else {
748	      // Look for a new potential minimum
749	      bool significant_descent = (last_new_z_ - current_z) > noise_threshold;
750	      bool is_ascending = (current_z > last_new_z_);
751	
752	      if (was_descending_ && is_ascending && (current_z - last_new_z_) > noise_threshold * 0.5) {
753	        // Potential minimum detected at previous frame
754	        has_pending_minimum_ = true;
755	        pending_min_index_ = static_cast<int>(frame_buffer_.size()) - 2;  // Previous frame
756	        if (pending_min_index_ < 0) pending_min_index_ = 0;
757	        frames_since_minimum_ = 1;
758	      }
759	
760	      // Update descending flag

 761	      if (significant_descent) {
 762	        was_descending_ = true;
 763	      }
 764	    }
 765	
 766	    last_new_z_ = current_z;
 767	  }
