 769	  /**
 770	   * Confirm the landing point and calculate weighted average coordinates.
 771	   * Weight formula: w_i = 1 / (|Z_i - Z_min| + epsilon)
 772	   * This gives higher weight to frames with Z closer to the minimum.
 773	   */
 774	  void ConfirmLandingPoint() {
 775	    if (pending_min_index_ < 0 || pending_min_index_ >= static_cast<int>(frame_buffer_.size())) {
 776	      return;
 777	    }
 778	
 779	    // Find the actual minimum Z in the buffer (in case of noise)
 780	    double min_z = frame_buffer_[pending_min_index_].z;
 781	    int actual_min_idx = pending_min_index_;
 782	
 783	    // Search nearby frames for the actual minimum
 784	    int search_start = std::max(0, pending_min_index_ - 3);
 785	    int search_end = std::min(static_cast<int>(frame_buffer_.size()) - 1, pending_min_index_ + 3);
 786	
 787	    for (int i = search_start; i <= search_end; i++) {
 788	      if (frame_buffer_[i].z < min_z) {
 789	        min_z = frame_buffer_[i].z;
 790	        actual_min_idx = i;
 791	      }
 792	    }
 793	
 794	    // Define the window for weighted averaging (use member variable)
 795	    int window_start = std::max(0, actual_min_idx - window_half_);
 796	    int window_end = std::min(static_cast<int>(frame_buffer_.size()) - 1, actual_min_idx + window_half_);
 797	
 798	    // Calculate weighted average
 799	    constexpr double epsilon = 1.0;  // Prevent division by zero
 800	    double weight_sum = 0.0;
 801	    double weighted_x = 0.0;
 802	    double weighted_y = 0.0;
 803	
 804	    for (int i = window_start; i <= window_end; i++) {
 805	      double z_diff = std::abs(frame_buffer_[i].z - min_z);
 806	      double weight = 1.0 / (z_diff + epsilon);
 807	
 808	      weighted_x += weight * frame_buffer_[i].x;
 809	      weighted_y += weight * frame_buffer_[i].y;
 810	      weight_sum += weight;
 811	    }
 812	
 813	    // Calculate final coordinates
 814	    double final_x = weighted_x / weight_sum;
 815	    double final_y = weighted_y / weight_sum;
 816	
 817	    // Calculate time since start
 818	    auto min_timestamp = frame_buffer_[actual_min_idx].timestamp;
 819	    auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
 820	        min_timestamp - start_time_).count();
 821	    int total_seconds = static_cast<int>(elapsed_ms / 1000);
 822	    int minutes = total_seconds / 60;
 823	    int seconds = total_seconds % 60;
 824	
 825	
 826	          // Enforce minimum interval between landing points (debounce)
 827	          // User requirement: 400ms
 828	          if (last_landing_time_initialized_) {
 829	              auto delta_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
 830	                  min_timestamp - last_landing_time_).count();
 831	              if (delta_ms < kMinLandingIntervalMs) {
 832	                  // Update last_landing_time_ to suppress rapid retriggers
 833	                  last_landing_time_ = min_timestamp;
 834	                  return;
 835	                }
 836	            }
 837	          last_landing_time_ = min_timestamp;
 838	          last_landing_time_initialized_ = true;
 839	
 840	    // Create landing point record
 841	    LandingPoint lp;
 842	    lp.time_minutes = minutes;
 843	    lp.time_seconds = seconds;
 844	    lp.t_ms_since_start = elapsed_ms;  // 精确时间戳
 845	    lp.new_frame_x = final_x;
 846	    lp.new_frame_y = final_y;
 847	    lp.new_frame_z = min_z;
 848	    lp.landing_id = 0;  // Will be assigned if recorded
 849	
 850	    // Record the landing point (decides whether to store based on record_enabled)
 851	    RecordLandingPoint(lp, window_end - window_start + 1);
 852	  }
