 854	  /**
 855	   * Record a landing point - decides whether to store based on record_enabled flag.
 856	   * This function is decoupled from ConfirmLandingPoint() for flexibility.
 857	   */
 858	  void RecordLandingPoint(LandingPoint& lp, int window_size) {
 859	    // Only store landing point if recording is enabled
 860	    if (g_runtime_flags.record_enabled) {
 861	      landing_count_++;
 862	      lp.landing_id = landing_count_;
 863	      landing_points_.push_back(lp);
 864	
 865	      // Output to console with detailed info
