 874	    std::cout << "  时间: " << lp.time_minutes << "分" << lp.time_seconds << "秒 (t_ms: " << lp.t_ms_since_start << ")" << std::endl;
 875	    std::cout << "  新坐标系 X: " << std::fixed << std::setprecision(1) << lp.new_frame_x << " mm" << std::endl;
