 970	  void DrawFluctuationCurve(cv::Mat &im, int start_y) {
 971	    if (z_history_.size() < 2) {
 972	      return;
 973	    }
 974	
 975	    const int graph_height = 150;
 976	    const int graph_width = 600;
 977	    const int margin_left = 10;
 978	    const int margin_bottom = 20;
 979	
 980	    // Draw background
 981	    cv::rectangle(im,
 982	                  cv::Point(margin_left, start_y),
 983	                  cv::Point(margin_left + graph_width, start_y + graph_height),
 984	                  cv::Scalar(240, 240, 240), -1);
 985	
 986	    // Find min and max for scaling
 987	    double min_z = *std::min_element(z_history_.begin(), z_history_.end());
 988	    double max_z = *std::max_element(z_history_.begin(), z_history_.end());
 989	    double range = max_z - min_z;
 990	    if (range < 10) range = 10;  // Minimum range for visibility
 991	
 992	    // Draw curve
 993	    for (size_t i = 1; i < z_history_.size(); i++) {
 994	      double z1 = z_history_[i - 1];
 995	      double z2 = z_history_[i];
 996	
 997	      int x1 = margin_left + (i - 1) * graph_width / max_history_size_;
 998	      int x2 = margin_left + i * graph_width / max_history_size_;
 999	
1000	      int y1 = start_y + graph_height - margin_bottom -
1001	               ((z1 - min_z) / range) * (graph_height - margin_bottom - 10);
1002	      int y2 = start_y + graph_height - margin_bottom -
1003	               ((z2 - min_z) / range) * (graph_height - margin_bottom - 10);
1004	
1005	      cv::line(im, cv::Point(x1, y1), cv::Point(x2, y2),
1006	               cv::Scalar(0, 0, 255), 2);  // Red curve
1007	    }
1008	
1009	    // Draw axes
1010	    cv::line(im,
1011	             cv::Point(margin_left, start_y + graph_height - margin_bottom),
1012	             cv::Point(margin_left + graph_width, start_y + graph_height - margin_bottom),
1013	             cv::Scalar(0, 0, 0), 2);  // X axis
1014	
1015	    // Draw labels
1016	    std::ostringstream title_str;
1017	    title_str << "Z-coordinate Fluctuation (Last " << max_history_size_ << " frames)";
1018	    cv::putText(im, title_str.str(),
1019	                cv::Point(margin_left, start_y - 5),
1020	                cv::FONT_HERSHEY_PLAIN, 1.2, cv::Scalar(0, 0, 0), 1);
1021	
1022	    std::ostringstream range_str;
1023	    range_str << "Range: " << std::fixed << std::setprecision(1)
1024	              << min_z << " - " << max_z << " mm (Variation: "
1025	              << (max_z - min_z) << " mm)";
1026	    cv::putText(im, range_str.str(),
1027	                cv::Point(margin_left, start_y + graph_height + 15),
1028	                cv::FONT_HERSHEY_PLAIN, 1.0, cv::Scalar(100, 100, 100), 1);
1029	  }
