1043	  static bool FitPlaneLeastSquares(const std::vector<cv::Point3d>& pts, cv::Vec4d& plane) {
1044	    if (pts.size() < 3) return false;
1045	    cv::Point3d mean(0, 0, 0);
1046	    for (const auto& p : pts) {
1047	      mean.x += p.x;
1048	      mean.y += p.y;
1049	      mean.z += p.z;
1050	    }

1051	    mean.x /= static_cast<double>(pts.size());
1052	    mean.y /= static_cast<double>(pts.size());
1053	    mean.z /= static_cast<double>(pts.size());
1054	
1055	    double xx = 0.0, xy = 0.0, xz = 0.0, yy = 0.0, yz = 0.0, zz = 0.0;
1056	    for (const auto& p : pts) {
1057	      double dx = p.x - mean.x;
1058	      double dy = p.y - mean.y;
1059	      double dz = p.z - mean.z;
1060	      xx += dx * dx;
1061	      xy += dx * dy;
1062	      xz += dx * dz;
1063	      yy += dy * dy;
1064	      yz += dy * dz;
1065	      zz += dz * dz;
1066	    }
1067	
1068	    cv::Mat cov = (cv::Mat_<double>(3, 3) << xx, xy, xz,
1069	                                             xy, yy, yz,
1070	                                             xz, yz, zz);
1071	    cv::Mat eigen_vals, eigen_vecs;
1072	    cv::eigen(cov, eigen_vals, eigen_vecs);
1073	    cv::Vec3d n(eigen_vecs.at<double>(2, 0),
1074	                eigen_vecs.at<double>(2, 1),
1075	                eigen_vecs.at<double>(2, 2));
1076	    double norm = std::sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);
1077	    if (norm < 1e-9) return false;
1078	    n /= norm;
1079	    double d = -(n[0] * mean.x + n[1] * mean.y + n[2] * mean.z);
1080	    plane = cv::Vec4d(n[0], n[1], n[2], d);
1081	    return true;
1082	  }
1083	
1084	  static bool FitPlaneRansac(const std::vector<cv::Point3d>& pts,
1085	                             int max_iters,
1086	                             double inlier_thresh,
1087	                             std::vector<int>& best_inliers,
1088	                             cv::Vec4d& best_plane) {
1089	    best_inliers.clear();
1090	    if (pts.size() < 3) return false;
1091	
1092	    std::random_device rd;
1093	    std::mt19937 gen(rd());
1094	    std::uniform_int_distribution<> dis(0, static_cast<int>(pts.size()) - 1);
1095	
1096	    for (int iter = 0; iter < max_iters; ++iter) {
1097	      int i1 = dis(gen);
1098	      int i2 = dis(gen);
1099	      int i3 = dis(gen);
1100	      if (i1 == i2 || i1 == i3 || i2 == i3) {
1101	        --iter;
1102	        continue;
1103	      }
1104	
1105	      const auto& p1 = pts[i1];
1106	      const auto& p2 = pts[i2];
1107	      const auto& p3 = pts[i3];
1108	
1109	      cv::Vec3d v1(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
1110	      cv::Vec3d v2(p3.x - p1.x, p3.y - p1.y, p3.z - p1.z);
1111	      cv::Vec3d n = v1.cross(v2);
1112	      double norm = std::sqrt(n.dot(n));
1113	      if (norm < 1e-9) continue;
1114	      n /= norm;
1115	      double d = -(n[0] * p1.x + n[1] * p1.y + n[2] * p1.z);
1116	
1117	      std::vector<int> inliers;
1118	      inliers.reserve(pts.size());
1119	      for (int i = 0; i < static_cast<int>(pts.size()); ++i) {
1120	        const auto& p = pts[i];
1121	        double dist = std::abs(n[0] * p.x + n[1] * p.y + n[2] * p.z + d);
1122	        if (dist < inlier_thresh) {
1123	          inliers.push_back(i);
1124	        }
1125	      }
1126	
1127	      if (inliers.size() > best_inliers.size()) {
1128	        best_inliers.swap(inliers);
1129	        best_plane = cv::Vec4d(n[0], n[1], n[2], d);
1130	        if (best_inliers.size() > pts.size() * 0.85) {
1131	          break;
1132	        }
1133	      }
1134	    }
1135	
1136	    return best_inliers.size() >= 10;
1137	  }
