1139	  bool PixelToPlanePoint(const cv::Point& px, const cv::Vec4d& plane, cv::Point3d& out) const {
1140	    cv::Mat ray = cv_in_left_inv * (cv::Mat_<double>(3, 1) << static_cast<double>(px.x),
1141	                                   static_cast<double>(px.y), 1.0);
1142	    cv::Vec3d dir(ray.at<double>(0, 0), ray.at<double>(1, 0), ray.at<double>(2, 0));
1143	    cv::Vec3d n(plane[0], plane[1], plane[2]);
1144	    double denom = n.dot(dir);
1145	    if (std::abs(denom) < 1e-9) return false;
1146	    double t = -plane[3] / denom;
1147	    if (t <= 0.0) return false;
1148	    out = cv::Point3d(dir[0] * t, dir[1] * t, dir[2] * t);
1149	    return true;
1150	  }
1151	
1152	  bool BuildFrameFromPlane(const cv::Vec4d& plane, const std::vector<cv::Point3d>& inliers) {
1153	    if (roi_points_.size() < 4 || inliers.size() < 3) return false;
1154	    cv::Vec3d Z_vec(plane[0], plane[1], plane[2]);
1155	    double zn = std::sqrt(Z_vec.dot(Z_vec));
1156	    if (zn < 1e-9) return false;
1157	    Z_vec /= zn;
1158	
1159	    // Assume camera Y+ is down; ensure "up" is negative Y.
1160	    if (Z_vec[1] > 0.0) {
1161	      Z_vec = -Z_vec;
1162	    }
1163	
1164	    int best_idx = 0;
1165	    double best_len = -1.0;
1166	    for (int i = 0; i < 4; ++i) {
1167	      int j = (i + 1) % 4;
1168	      double dx = static_cast<double>(roi_points_[j].x - roi_points_[i].x);
1169	      double dy = static_cast<double>(roi_points_[j].y - roi_points_[i].y);
1170	      double len = std::sqrt(dx * dx + dy * dy);
1171	      if (len > best_len) {
1172	        best_len = len;
1173	        best_idx = i;
1174	      }
1175	    }
1176	    int idx1 = best_idx;
1177	    int idx2 = (best_idx + 1) % 4;
1178	    if (roi_points_[idx2].x < roi_points_[idx1].x) {
1179	      std::swap(idx1, idx2);
1180	    }
1181	
1182	    cv::Point3d p1, p2;
1183	    if (!PixelToPlanePoint(roi_points_[idx1], plane, p1) ||
1184	        !PixelToPlanePoint(roi_points_[idx2], plane, p2)) {
1185	      return false;
1186	    }
1187	
1188	    cv::Vec3d X_vec(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
1189	    double xn = std::sqrt(X_vec.dot(X_vec));
1190	    if (xn < 1e-9) return false;
1191	    X_vec /= xn;
1192	
1193	    // Ensure X lies in plane and orthogonal to Z
1194	    X_vec = X_vec - Z_vec * (X_vec.dot(Z_vec));
1195	    xn = std::sqrt(X_vec.dot(X_vec));
1196	    if (xn < 1e-9) return false;
1197	    X_vec /= xn;
1198	
1199	    cv::Vec3d Y_vec = cv::Vec3d(Z_vec).cross(X_vec);
1200	    double yn = std::sqrt(Y_vec.dot(Y_vec));
1201	    if (yn < 1e-9) return false;
1202	    Y_vec /= yn;
1203	
1204	    // Re-orthonormalize X to keep right-handed frame
1205	    X_vec = Y_vec.cross(Z_vec);
1206	    xn = std::sqrt(X_vec.dot(X_vec));
1207	    if (xn < 1e-9) return false;
1208	    X_vec /= xn;
1209	
1210	    rotation_matrix_.at<double>(0, 0) = X_vec[0];
1211	    rotation_matrix_.at<double>(1, 0) = X_vec[1];
1212	    rotation_matrix_.at<double>(2, 0) = X_vec[2];
1213	
