 6	bool RobustDepthMedianU16(const cv::Mat& depth_mm, int x, int y, int r,
 7	                          uint16_t& out_mm) {
 8	  if (depth_mm.empty() || depth_mm.type() != CV_16UC1) return false;
 9	  std::vector<uint16_t> vals;
10	  vals.reserve((2 * r + 1) * (2 * r + 1));
11	  for (int dy = -r; dy <= r; ++dy) {
12	    int yy = y + dy;
13	    if (yy < 0 || yy >= depth_mm.rows) continue;
14	    const uint16_t* row = depth_mm.ptr<uint16_t>(yy);
15	    for (int dx = -r; dx <= r; ++dx) {
16	      int xx = x + dx;
17	      if (xx < 0 || xx >= depth_mm.cols) continue;
18	      uint16_t z = row[xx];
19	      // filter invalid (0) / out-of-range
20	      if (z == 0 || z >= 10000) continue;
21	      vals.push_back(z);
22	    }
23	  }
24	  if (vals.size() < 6) return false;  // too few valid samples
25	  std::nth_element(vals.begin(), vals.begin() + vals.size() / 2, vals.end());
26	  out_mm = vals[vals.size() / 2];
27	  return true;
28	}

