39	  auto calc_stats = [](const std::deque<double>& data) -> std::pair<double, double> {
40	    if (data.empty()) return {0, 0};
41	    double sum = 0, max_val = 0;
42	    for (double v : data) { sum += v; if (v > max_val) max_val = v; }
43	    return {sum / data.size(), max_val};
44	  };
45	
46	  auto [inf_avg, inf_max] = calc_stats(inference_ms);
47	  auto [dep_avg, dep_max] = calc_stats(depth_map_ms);
48	  auto [land_avg, land_max] = calc_stats(landing_detect_ms);
49	
50	  std::cout << "[Perf] Inference: " << std::fixed << std::setprecision(1)
51	            << inf_avg << "/" << inf_max << "ms"
52	            << " | Depth: " << dep_avg << "/" << dep_max << "ms"
53	            << " | Landing: " << land_avg << "/" << land_max << "ms" << std::endl;
54	}

